package org.fruittwingpt.config;
import com.nimbusds.jose.jwk.source.ImmutableSecret; import com.nimbusds.jose.proc.SecurityContext; import javax.crypto.spec.SecretKeySpec; import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.oauth2.jose.jws.MacAlgorithm; import org.springframework.security.oauth2.jwt.*; import org.springframework.security.web.SecurityFilterChain; import org.springframework.web.cors.*; import java.nio.charset.StandardCharsets; import java.security.SecureRandom; import java.util.Base64; import java.util.List;
@Configuration public class SecurityConfig { @Value("${app.jwt.secret}") String secret; @Value("${app.local-development:false}") boolean localDevelopment; @Value("${app.cors-origin}") String corsOrigin;
 private byte[] key(){ if(secret==null||secret.length()<32) { if(!localDevelopment) throw new IllegalStateException("JWT_SECRET must contain at least 32 characters"); var bytes=new byte[48]; new SecureRandom().nextBytes(bytes); secret=Base64.getUrlEncoder().withoutPadding().encodeToString(bytes); } return secret.getBytes(StandardCharsets.UTF_8); }
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean JwtEncoder jwtEncoder(){return new NimbusJwtEncoder(new ImmutableSecret<SecurityContext>(new SecretKeySpec(key(),"HmacSHA256")));} @Bean JwtDecoder jwtDecoder(){return NimbusJwtDecoder.withSecretKey(new SecretKeySpec(key(),"HmacSHA256")).macAlgorithm(MacAlgorithm.HS256).build();}
 @Bean SecurityFilterChain filterChain(HttpSecurity http) throws Exception { return http.csrf(c->c.disable()).cors(c->{}).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**","/actuator/health","/v3/api-docs/**","/docs/**","/swagger-ui/**").permitAll().anyRequest().authenticated()).oauth2ResourceServer(o->o.jwt(j->{})).build(); }
 @Bean CorsConfigurationSource corsConfigurationSource(){ var c=new CorsConfiguration();c.setAllowedOrigins(List.of(corsOrigin));c.setAllowedMethods(List.of("GET","POST","PUT","DELETE","OPTIONS"));c.setAllowedHeaders(List.of("Authorization","Content-Type"));var s=new UrlBasedCorsConfigurationSource();s.registerCorsConfiguration("/api/**",c);return s; }
}
